            files.push_back(entry.path().string());  // 将路径添加到文件列表中
        }
    }
    return files;
}

void data_clean(Data& df) {
    // 去重：移除重复的记录
    auto it = unique(df.texts.begin(), df.texts.end());
    df.texts.erase(it, df.texts.end());

    // 处理缺失值，默认填充为空字符串
    fill(df.texts.begin(), df.texts.end(), "");

    // 时间格式转换：将时间字符串转换为time_t类型
    map<string, time_t> datetime_map;  // 存储日期时间字符串与time_t的映射关系
    for (size_t i = 0; i < df.texts.size(); ++i) {
        string datetime_str = df.texts[i];
        time_t now;
        if (strptime(&now, "%Y-%m-%d %H:%M:%S") != nullptr && 
            strcmp(datetime_str.c_str(), strtok(&now, "%")) == 0) {  // 检查日期格式是否一致
            datetime_map[datetime_str] = now;  // 记录时间戳
        }
    }

    // 文本标准化：去掉特殊符号并分词
    for (size_t i = 0; i < df.texts.size(); ++i) {
        string sanitized;  // 用于存储清洗后的文本内容
        for (char c : df.texts[i]) {  // 遍历单个字符
            if (isalpha(c)) {  // 检查是否是字母
                sanitized += tolower(c);  // 转换为小写并追加到sanitized字符串中
            }
        }

        vector<string> words;  // 用于存储分词后的结果
        istringstream iss(sanitized);  // 使用istringstream进行分词操作
        string word;
        while (iss >> word) {  // 分词处理
            words.push_back(word);
        }

        // 将分词结果合并为一个字符串，替换原文本内容
        if (!words.empty()) {
            df.texts[i] = join(words, " ");  // 合并单词，并用空格连接
        } else {
            df.texts[i] = "";  // 未能分词的情况下，设置为空字符串
        }
    }
}

void processFile(const string& file, const string& data_dir, Data& result) {
    try {
        // 打开文件流
        ifstream infile(os.path.join(data_dir, file));
        if (!infile.is_open()) {  // 检查是否成功打开文件
            throw runtime_error("无法打开文件: " + file);
        }

        vector<string> texts;  // 用于存储文本数据

        string line;
        while (getline(infile, line)) {  // 逐行读取文件内容
            if (line.empty()) continue;  // 跳过空行
            texts.push_back(line);  // 将每一行添加到文本列表中
        }

        // 清洗和预处理数据
        data_clean({texts});

        // 更新结果
        result.texts = move(texts);

        cout << "文件" << file << "已成功处理!" << endl;  // 输出处理状态
    } catch (const exception& e) {  // 捕获并处理异常
        cerr << "错误：处理文件" << file << ": " << e.what() << endl;  // 输出错误信息
    }
}

