            map<string, int> problem_counts;  // 记录问题类型及其出现次数
            map<double, string> sentiment_map;  // 记录情感得分及对应的满意度等级
            vector<double> response_times;  // 记录每条记录的响应时间

            for (const string& text : result.texts) {  // 遍历所有文本数据
